-- local Services & Natives (Lưu biến local ngay khi nạp để tránh bị Metatable/Index Hook)
local task_wait = task.wait
local task_spawn = task.spawn
local pcall = pcall
local type = type
local rawget = rawget
local getfenv = getfenv
local string_sub = string.sub
local debug_info = debug.info

local Players = game:GetService("Players")
local LocalPlayer = Players.LocalPlayer

-- Global Check Bypass Detection
local original_loadstring = loadstring

-- ==========================================
-- 1. HÀM THỰC THI KICK BẢO MẬT
-- ==========================================
local function executeKick()
    -- Thực hiện kick
    pcall(function()
        LocalPlayer:Kick("Hook kick")
    end)
    
    -- Nếu bị hook hàm Kick(), tạo crash loop để vô hiệu hóa hoàn toàn môi trường Lua client
    while true do
        task_wait()
        LocalPlayer:Destroy()
    end
end

-- ==========================================
-- 2. ĐỘI NGŨ KIỂM TRA ĐA LỚP (MULTI-LAYER ANTI-HOOK)
-- ==========================================

-- A. Kiểm tra Metatable của Global (__index / __newindex hooks)
local function checkMetatableTamper()
    local env = getfenv(0)
    local meta = getmetatable(env)
    
    if meta then
        -- Kẻ gian thường can thiệp metatable môi trường để chặn đọc/ghi loadstring
        if rawget(meta, "__index") or rawget(meta, "__newindex") or rawget(meta, "__namecall") then
            return true
        end
    end
    return false
end

-- B. Kiểm tra tính toàn vẹn của hàm loadstring
local function isLoadstringHooked()
    -- Test 1: Kiểm tra sự tồn tại và gán biến
    if not loadstring or loadstring ~= original_loadstring then
        return true
    end
    
    if type(loadstring) ~= "function" then
        return true
    end

    -- Test 2: Debug Info Integrity (C-Closure Check)
    local success, source, line, what = pcall(function()
        return debug_info(loadstring, "sln")
    end)

    if not success or not source or not what then
        return true
    end

    -- Hàm C nguyên bản luôn có source là "[C]" hoặc "=[C]" và what là "C"
    if what ~= "C" or (source ~= "[C]" and source ~= "=[C]") then
        return true
    end

    -- Test 3: iscclosure / isluacclosure check (Dành cho môi trường Executor)
    if iscclosure and not iscclosure(loadstring) then
        return true
    end
    if islclosure and islclosure(loadstring) then
        return true
    end

    -- Test 4: Kiểm tra phản ứng thực thi thực tế (Functional Integrity Check)
    -- Giả lập một lệnh loadstring chuẩn để xem phản ứng có bị can thiệp/ghim log dump hay không
    local testPass, testResult = pcall(function()
        return loadstring("return 123456")
    end)

    if not testPass or type(testResult) ~= "function" then
        return true
    end

    local execPass, execValue = pcall(testResult)
    if not execPass or execValue ~= 123456 then
        return true
    end

    return false
end

-- C. Kiểm tra sự xuất hiện của các công cụ Hook / Dump phổ biến
local function checkExploitEnvironment()
    local env = getfenv(0)
    
    -- Kiểm tra sự xuất hiện của các hàm nguy hiểm
    local blacklistFunctions = {
        "hookfunction", "replaceclosure", "hookmetamethod",
        "newcclosure", "decompile", "saveinstance",
        "getgc", "getnilinstances", "getreg", "getrenv"
    }

    for _, funcName in ipairs(blacklistFunctions) do
        if rawget(env, funcName) or rawget(_G, funcName) then
            return true
        end
    end

    return false
end

-- ==========================================
-- 3. VÒNG LẶP GIÁM SÁT REAL-TIME (Anti-Bypass Loop)
-- ==========================================
task_spawn(function()
    local lastTick = os.clock()

    while true do
        -- Kiểm tra xem vòng lặp có bị đóng băng / làm chậm (Anti-Freeze / Anti-Yield)
        local currentTick = os.clock()
        lastTick = currentTick

        -- Tiến hành quét
        if isLoadstringHooked() or checkMetatableTamper() or checkExploitEnvironment() then
            executeKick()
            break
        end

        -- Tần số quét cao (0.1 giây) để phát hiện hook ngay khi vừa tiêm script
        task_wait(0.1)
    end
end)


